"proposal": {
  "capability": "deployment.set-probes",
  "target": {
    "group": "apps",
    "kind": "Deployment",
    "namespace": "edge",
    "name": "api-gateway",
    "uid": "uid-deployment-api-gateway"
  },
  "params": {
    "container": "app",
    "liveness": {
      "initialDelaySeconds": 90,
      "timeoutSeconds": 30
    }
  },
  "expected_effect": "The liveness probe will wait longer for the app to start, preventing premature restarts.",
  "rationale": "The container ran for 1m2s before being killed, and logs show route reload is slow in 1.20. The liveness probe's initial delay (10s) and timeout (1s) were too strict. Increasing initialDelaySeconds to 90 and timeoutSeconds to 30 aligns with the Notice event's suggestion and allows the app to initialize properly.",
  "cited_evidence_ids": ["ev-rollout_history", "ev-pod_states", "ev-target_events", "ev-container_logs_tail"],
  "cited_predicates": ["killed_during_startup", "probe_kills", "probe_timeouts"]
